INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (128, 202, 'Plus-Wax Ribbon (enhance)', '../upload/image/20181226/20181226145510_78403.jpg', '<p></p><p>Plus-Wax Ribbon (enhance)<br/> Feature:<br/> Extensive label adaptability <br/> Good stability of products <br/> High definition <br/> Low print energy can extend the life of protect print head <br/> Anti-static back coating can protect print head effectively <br/> Good abrasion resistance <br/> Introduction:<br/> with excellent anti-static property and outstanding print quality,have the good print quality and the better label adaptability by using the high property printer and the simplified tabletop printer.The print speed can be up to 6 ips.It is suitable for many different types of label stocks. Premium wax has longer storage time, the better product stability, excellent heat resistance and abrasion, making the printed picture much more durable, clear and smooth..<br/> Print material:<br/> Recommended substrates:<br/> Art paper, coated paper, uncoated paper, glossy &amp; semi glossy paper, hangtag.<br/> Application field??<br/> Price Label, Product Identification Label, Hang Tag, Packing Label, Train Tickets, Shipping &amp; Receiving Label, Logistical Label.<br/> Technical parameters:<br/> Test Item Unit Test Equipment Standard<br/> Total thickness Um Thickness Tester 7.0+0.2<br/> Ink thickness Um Thickness Tester 2.6+0.4<br/> Electrostatic K v Static Tester 0.05<br/> Optical density D Transmission Type Density Spectrometer 1.4<br/> Color density D B Reflex density spectrometer 2.7<br/> Glossiness Gs Vancometer 55</p> <p><br/></p>', '2026-09-06 20:58:45');